package com.nexamart.backend.repository;
import com.nexamart.backend.domain.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;
public interface UserAccountRepository extends JpaRepository<UserAccount,Long>{Optional<UserAccount> findByEmailIgnoreCase(String email);Optional<UserAccount> findByUsernameIgnoreCase(String username);Optional<UserAccount> findByPhone(String phone);List<UserAccount> findAllByPhoneOrderByIdAsc(String phone);boolean existsByEmailIgnoreCase(String email);boolean existsByPhone(String phone);boolean existsByUsernameIgnoreCase(String username);Page<UserAccount> findByRole(Role role,Pageable p);@Query("select u from UserAccount u where u.role=:role and (:q is null or lower(u.name) like lower(concat('%',:q,'%')) or lower(u.email) like lower(concat('%',:q,'%')) or u.phone like concat('%',:q,'%')) and (:status is null or u.status=:status)")Page<UserAccount> search(@Param("role")Role role,@Param("q")String q,@Param("status")AccountStatus status,Pageable p);}
